"""Report only recorded full-cycle evidence in the existing consolidated report."""
import json
from pathlib import Path
import numpy as np

def dynamic_rows(P):
 def fmt(x):return 'failed' if x is None else f'{x:.6g}'
 def load(name):return json.loads((P/f'experiments/metrics/{name}.json').read_text())
 manifest=P/'experiments/manifests/cardiac_dynamic_v1.json'
 if not manifest.exists():return []
 m=json.loads(manifest.read_text());rows=['','**Full-cycle follow-up (2026-10-17).** This is a new passive numerical benchmark task. The earlier1ms acceleration-increment model remains a failed recursive pilot; the new model uses5ms steps and a different recurrent formulation. Stability improvements cannot be attributed to one change alone. No active electromechanical or clinical claim follows.','', '**Protocol and split.** Thirty-two independent numerical geometry draws from one affine benchmark ellipsoid family. Eight training trajectories on four geometries, four validation trajectories on two geometries, twenty calibration trajectories on twenty geometries, and four primary test trajectories on four geometries. Four additional loading-shift trajectories share the four test geometries; four combined shape/loading-shift trajectories use two further geometries. All are200-step trajectories from zero histories over0.005–1s. No geometry spans training/validation/calibration/test roles. Calibration and primary test independently draw the same numerical shape and waveform-descriptor distribution. Load amplitude/timing perturbations are numerical sensitivity inputs, not empirical physiology.', '',f'Reference collection: {m["completed_accepted_trajectories"]}/{m["planned_accepted_trajectories"]} planned accepted trajectories complete, including convergence variants. The44-trajectory cohort is separate from these convergence repeats. Every newly accepted step requires a positive SNES convergence reason, finite residual below1e-6N and positive endpoint element determinants. Failed10ms attempts and refined5ms retries are retained. The source legacy convergence flag could be negative/truthy; explicit positive-reason checks correct that issue. Earlier archived1ms states were independently checked to have finite small residuals.', '', '**Neural method and controls.** A64-node graph encoder (width32, two message rounds) conditions a64-state GRU. Each update receives the previous predicted displacement coefficients and current/previous prescribed pressure. A bounded tanh readout returns rank12 uncentered POD coefficients. The hidden state and displacement start at zero; all200 predictions are generated without true displacement/velocity/acceleration histories. Bounded coefficients do not mathematically guarantee positive Jacobians or mechanical equilibrium. Endpoint Jacobians are checked separately.', '', 'POD and coefficient/derivative scales use labelled training fields only. The displacement loss is physical field MSE divided by training field RMS squared, with0.1/0.01 physically scaled first/second time-difference losses. Exact orthonormal-POD identities evaluate these losses in coefficient space. The initial equal-normalized-mode pilot is preserved as a validation-only unsuccessful design. Matched arms share400 warm supervised updates, then250 further data-only or physics updates from exactly the same warm checkpoint. The warm checkpoint remains eligible. Five seeds11/22/33/44/55 are used. Physics weight grids come from training-only parameter-gradient balance and are selected on native float64 validation force residual subject to at most10% displacement-RMSE degradation.', '', 'The full regime labels all four training geometries. The limited regime labels only one geometry/two trajectories, fits its own POD/scales, and uses the remaining three training geometries as unlabelled residual collocation inputs. Their displacement/history arrays are not read by limited-data preprocessing. Both arms have the same input descriptors and labelled targets; validation labels and optimizer budgets are matched. This limits training labels, not the total simulation cost of constructing this research cohort.', '', 'The full nonlinear weak residual includes source anisotropic passive elasticity, viscosity, generalized-alpha inertia, Robin terms and follower pressure. Histories are derived causally from the complete predicted displacement sequence through the exact source Newmark maps. CPU float32 neural training is linked differentiably to MPS float32 residual evaluation; final inference/mechanics use CPU/native float64. MPS scatter accumulation is not bitwise deterministic, despite seeded runs.']
 if (P/'experiments/metrics/dynamic_mesh_convergence.json').exists():
  spatial=load('dynamic_mesh_convergence');rows[2:2]=['',f'**Numerical validation gate remains unmet.** Full-cycle mesh refinement changes displacement by {spatial["relative_spacetime_volume_L2_difference"]:.2%}, exceeding the stated1% tolerance. The5ms temporal target also misses1%. All model improvements and calibration below refer to the coarse discrete reference; they exclude FE discretization uncertainty and do not establish continuum accuracy.']
 if (P/'experiments/metrics/dynamic_backend.json').exists():
  g=load('dynamic_backend');rows+=['',f'Independent5ms verification passed: largest CPU64 force/tangent relative error {max(max(r["cpu64_force_relative_error"],r["cpu64_u_gradient_relative_error"]) for r in g["records"]):.3g}; largest GPU32 force/tangent error {max(max(r["gpu32_force_relative_error"],r["gpu32_u_gradient_relative_error"]) for r in g["records"]):.3g}; coupled-history derivative relative error {max(r["history_chain_gradient_relative_error_vs_native_finite_difference"] for r in g["records"]):.3g}.']
 if (P/'experiments/metrics/dynamic_neural_gradient.json').exists():
  g=load('dynamic_neural_gradient');rows+=['',f'Actual frozen recurrent neural physics gradient verified against native directional finite differences through the complete predicted-history chain: norm{g["physics_only_network_parameter_gradient_norm"]:.6g}, relative discrepancy{g["relative_error"]:.3g}, training case only.']
 if (P/'experiments/metrics/dynamic_final_evaluation.json').exists():
  d=load('dynamic_final_evaluation');rows+=['', '**Frozen primary evaluation.** All20 selected checkpoints were hashed before held-out ML evaluation. The deployment candidate is chosen from ensemble validation only, before calibration/test labels are opened. Geometry-cluster bootstrap intervals condition on the fixed models and only four independent test geometries; they exclude retraining and FE uncertainty. Mechanics are evaluated at nine preregistered frames, including startup and the final endpoint. Inversions are checked over every tetrahedron and every one of200 endpoints, for ensembles and each individual test member.', '', '| Ensemble | Test component RMSE(mm) | Relative RMSE | Mean sampled force RMS | Complete non-inverted cycles | Min endpoint detF |','|---|---:|---:|---:|---:|---:|']
  for key,r in d['models'].items():
   t=r['splits']['test'];rows.append(f'| {key} | {t["mean_component_rmse_m"]*1000:.6f} | {np.mean([c["relative_component_rmse"] for c in t["per_case"]]):.3%} | {fmt(t["mean_sampled_normalized_force_rms"])} | {t["full_cycles_without_inversions"]}/{t["n_trajectories"]} | {t["minimum_detF"]:.5f} |')
  rows+=['', '| Regime | Physics/data RMSE ratio | Paired mean force-RMS difference | Conditional geometry bootstrap95% interval |','|---|---:|---:|---|']
  for regime,r in d['comparisons'].items():rows.append(f'| {regime} | {r["RMSE_ratio_physics_over_data"]:.6f} | {fmt(r["paired_geometry_mean_force_RMS_difference_physics_minus_data"])} | {r["conditional_geometry_bootstrap95"]} |')
  rows+=['',f'Validation-selected deployment candidate: **{d["preferred_from_validation_only"]}**. Per-seed displacement/mechanical errors, per-case strain/energy errors, invalid fields and conditional comparisons are in dynamic_final_evaluation.json. Lower residual must be considered together with displacement error and failure counts; no population-level significance claim is supported by four test geometries.', '', '**Joint trajectory calibration.** Each score is the maximum nodal L2 displacement error across all4577 nodes and all200 time steps for one independent geometry/waveform pair. Twenty separate calibration geometries permit finite corrected90% and95% radii. These balls target the coarse5ms numerical reference, not continuum or patient truth.', '', '| Ensemble | Nominal | Joint test geometry coverage | Radius(mm) | Exact binomial95% interval |','|---|---:|---:|---:|---|']
  for key,r in d['models'].items():
   for c in r['splits']['test']['coverage']:rows.append(f'| {key} | {c["nominal"]:.0%} | {c["covered"]}/{c["n"]} | {c["radius_m"]*1000:.4f} | {c["binomial95"]} |')
  rows+=['', 'A four-geometry test gives very wide coverage intervals. Raw ensemble variance is reported separately and is not a calibrated interval. Uncertainty/error associations on only four cases are descriptive.', '', '**Changed loading and rejection.** Input support is fixed at radius scales[.95,1.05], amplitude[.9,1.1] and timing scale[.95,1.05]. Known requests outside these ranges, missing/nonfinite descriptors, or invalid predicted Jacobians route to FE. This is explicit support checking, not a learned detector of every possible distribution shift or a correctness guarantee inside the box. Shift errors below are NN errors before routing; FE reference replacements are never counted as NN accuracy.', '', '| Model | Shift type | NN RMSE(mm) | Non-inverted cycles | FE routes | Nominal90% joint geometry coverage |','|---|---|---:|---:|---:|---:|']
  for key,r in d['models'].items():
   for split in ['load_shift','shift']:
    t=r['splits'][split];c=t['coverage'][0];rows.append(f'| {key} | {split} | {t["mean_component_rmse_m"]*1000:.5f} | {t["full_cycles_without_inversions"]}/{t["n_trajectories"]} | {t["FE_routes"]}/{t["n_trajectories"]} | {c["covered"]}/{c["n"]} |')
  rows+=['', 'Shift coverage has no exchangeability guarantee; trajectories on the same geometry are grouped. Rejected requests incur FE latency. No globally rapid or universally reliable hybrid system is claimed.', '', '![Complete frozen rollouts and mechanics](figures/dynamic_full_cycle.png)', '', '![Input-support rejection and shifted NN errors](figures/dynamic_shift_fallback.png)', '', '![Actual full-cycle FE boundary prediction](figures/dynamic_mesh_prediction.png)']
 else:rows+=['', '**Current state:** model training and/or reference generation/evaluation is still in progress. No held-out full-cycle accuracy, inversion-free completion or coverage result is claimed yet.']
 if (P/'configs/physics/dynamic_confirmation.json').exists() and not (P/'experiments/metrics/dynamic_confirmation_evaluation.json').exists():
  rows+=['','**Independent confirmation in progress:** sixteen additional fixed geometry/waveform draws are being simulated/evaluated with the existing frozen models and unchanged calibration; no new held-out result is claimed until the confirmation JSON is complete.']
 if (P/'experiments/metrics/dynamic_confirmation_evaluation.json').exists():
  c=load('dynamic_confirmation_evaluation');rows+=['','**Independent fixed-model confirmation.** Sixteen additional geometry/waveform draws were specified in a fixed config after checkpoint freezing and before inspecting the primary test results. The checkpoint hashes, method choices, feature transformations and20 original calibration scores/radii remain unchanged. These sixteen draws match the primary/calibration numerical distribution. Results are reported separately for confirmation16 and descriptively pooled with primary4 as20 independent test geometries; they are not replacement test cases.', '', '| Model | Confirmation16 RMSE(mm) | Pooled20 RMSE(mm) | Pooled force RMS | Non-inverted pooled cycles | Min detF |','|---|---:|---:|---:|---:|---:|']
  for key,r in c['models'].items():
   t=r['pooled_primary_and_confirmation'];rows.append(f'| {key} | {r["confirmation"]["mean_component_rmse_m"]*1000:.6f} | {t["mean_component_rmse_m"]*1000:.6f} | {fmt(t["mean_sampled_normalized_force_rms"])} | {t["full_cycles_without_inversions"]}/{t["n_geometries"]} | {t["minimum_detF"]:.5f} |')
  rows+=['', '| Regime / test set | Physics/data RMSE ratio | Force-RMS difference | Conditional geometry bootstrap95% interval | Descriptive H1 criterion |','|---|---:|---:|---|---|']
  for regime,r in c['comparisons'].items():
   for split,t in r.items():rows.append(f'| {regime}/{split} | {t["RMSE_ratio_physics_over_data"]:.6f} | {fmt(t["paired_mean_force_RMS_difference_physics_minus_data"])} | {t["conditional_geometry_bootstrap95"]} | {t["H1_descriptive_supported"]} |')
  rows+=['', 'H1 criterion: lower mean force residual with at most10% displacement-RMSE degradation. Bootstrap intervals condition on the fixed5-member models and exclude retraining and FE discretization uncertainty. Confirmation member accuracy/force residuals are retained; all-endpoint inversion checks are for ensembles in confirmation and for ensembles/members in the primary study.', '', '| Model | Nominal | Pooled joint coverage | Radius(mm) | Exact binomial95% interval |','|---|---:|---:|---:|---|']
  for key,r in c['models'].items():
   for t in r['pooled_primary_and_confirmation']['coverage']:rows.append(f'| {key} | {t["nominal"]:.0%} | {t["covered"]}/{t["n"]} | {t["radius_m"]*1000:.4f} | {t["binomial95"]} |')
  rows+=['', 'Raw uncertainty/error Spearman correlations and selective-risk values are in dynamic_confirmation_evaluation.json. Full-label physics had weak uncertainty ranking in this execution despite its conservative calibrated coverage. Added confirmation increases the study to60 cohort trajectories across48 distinct numerical geometries, including20 calibration and20 independent primary/confirmation test geometries. All remain within ONE ellipsoid source family.', '', '![Independent geometry confirmation and uncertainty](figures/dynamic_confirmation.png)']
 if (P/'experiments/metrics/dynamic_fallback_execution.json').exists():
  f=load('dynamic_fallback_execution');rows+=['',f'Actual routing test: {f["case"]["id"]} rejected before NN execution and sent to an independent full FE trajectory; fresh-cache flag{not f["cache_existed_before_request"]}, observed wall{f["wall_seconds"]:.1f}s. This run overlapped cohort generation and is not an isolated latency benchmark. Inputs were geometry/loading descriptors and zero initial histories only.']
 if (P/'experiments/metrics/dynamic_time_convergence.json').exists():
  t=load('dynamic_time_convergence');rows+=['', '**Full-cycle reference numerical uncertainty.** Exact consistent-mass volume-L2 comparisons use199 common endpoints0.005–0.995s on the baseline geometry; the archived1ms trajectory excludes1s.', '', '| Timestep | Space-time volume-L2 discrepancy vs1ms | Volume/time component RMSE(µm) |','|---|---:|---:|']
  for c in t['cases']:rows.append(f'| {c["resolution"]} | {c["relative_spacetime_volume_L2_error_vs_dt001"]:.4%} | {c["volume_time_component_rmse_m"]*1e6:.3f} |')
  rows+=['', 'The5ms model task misses the preregistered1% temporal tolerance;2.5ms is below that tolerance relative to1ms. Refinement reduces the discrepancy, but1ms is not continuum truth and unequal timestep ratios do not establish an asymptotic rate. The reported NN error remains relative to the5ms discrete target.']
 if (P/'experiments/metrics/dynamic_mesh_convergence.json').exists():
  s=load('dynamic_mesh_convergence');rows+=['',f'Spatial full-cycle comparison at{s["dt_s"]*1000:g}ms: {s["mesh_tetrahedra"][0]} to{s["mesh_tetrahedra"][1]} tetrahedra, identical polyhedral domain/material/BC and the same interpolated continuous fiber fields. Space-time volume-L2 difference{s["relative_spacetime_volume_L2_difference"]:.3%}; volume/time component RMSE{s["volume_time_component_rmse_m"]*1e6:.3f}µm. Within1% tolerance:{s["within_1percent_spacetime_tolerance"]}. Two levels quantify spatial sensitivity; they do not establish asymptotic mesh convergence.', '', 'These FE discrepancies are from one baseline geometry/waveform and use volume-weighted norms; model tables use uniform nodal norms on other geometries. They cannot be added as independent random variances or used to claim continuum coverage. Finer held-out reference trajectories would be required to calibrate error against a mesh-independent target.', '', '![Whole-cycle mesh and timestep sensitivity](figures/dynamic_convergence.png)']
 pilot_config=P/'configs/physics/dynamic_dt001_pilot.json'
 if pilot_config.exists():
  name=json.loads(pilot_config.read_text())['name'];path=P/f'experiments/metrics/{name}.json'
  if path.exists():
   r=json.loads(path.read_text());rows+=['','**Matched original-timestep stability check.** A separate one-geometry/one-cycle, seed11 pilot uses the archived1ms pressure/reference trajectory. Train first600 frames, select on the next200, evaluate the already-inspected last199. This is a repeated temporal benchmark, not independent trajectory confirmation. Every999-step inference begins at zero and uses only prescribed pressure and its own predicted histories. A training-only15% relative field-RMSE gate excludes the trivial zero predictor; the initial version that selected zeros on low-motion validation is retained as a FAILED acceptance test, not a stability success.', '', '| Original1ms model | Whole-cycle RMSE(mm) | Late test-block RMSE(mm) | Training relative RMSE | Endpoint min detF | Stress-state min detF | Nontrivial/complete999 |','|---|---:|---:|---:|---:|---:|---|']
   for label,t in r['models'].items():rows.append(f'| {label} | {t["full_cycle_component_rmse_m"]*1000:.6f} | {t["test_block_component_rmse_m"]*1000:.6f} | {t["training_relative_RMSE"]:.3%} | {t["minimum_endpoint_detF"]:.5f} | {t["minimum_stress_state_detF"]:.5f} | {t["nontrivial_training_fit"] and t["full_cycle_noninverted"]} |')
   rows+=['', 'The late reference displacement RMS is only about0.079mm; late prediction errors are much larger than that signal. The result demonstrates stable, nontrivial full-cycle rollout at the ORIGINAL1ms timestep, but does not establish accurate long-horizon extrapolation. Architecture, representation and training changed together; no single-factor causal attribution is made. No population CI or temporal conformal claim is supported by one cycle.', '', '![Original1ms full-cycle rollout and remaining forecast error](figures/dynamic_dt001_rollout.png)']
 if (P/'experiments/metrics/dynamic_alpha_jacobians.json').exists():
  j=load('dynamic_alpha_jacobians');rows+=['',f'All-cell stress-state positivity audit: {j["n_ensemble_trajectories"]} complete ensemble trajectories across{j["n_independent_test_geometries"]} test geometries, all200 generalized-alpha states; minimum detF{j["minimum_stress_state_detF"]:.6f}, passed:{j["passed"]}. Endpoint positivity was checked separately. Positive determinants alone do not establish accurate mechanics.']
 if (P/'experiments/metrics/dynamic_runtime.json').exists():
  r=load('dynamic_runtime');rows+=['',f'**Matched full-cycle runtime.** Preferred{r["model"]}, CPU float64, two threads, same held-out geometry/loading and200-step task. Five-member full displacement mean plus coordinate variance: median{r["NN_resident_mean_and_variance"]["median_s"]*1000:.2f}ms resident, {r["NN_with_input_processing"]["median_s"]*1000:.2f}ms with warm input reads/pooling, {r["NN_with_endpoint_and_stress_state_J_checks"]["median_s"]*1000:.2f}ms with all-element endpoint/stress-state J checks. Matched FE nonlinear solves total median{r["FE_sum_nonlinear_solve_seconds"]["median_s"]:.2f}s ({r["median_speedup_input_processing"]:.1f}× against NN with preprocessing). Two fresh FE cycles were timed; NN repeats30/20/10 for these three scopes. Full-process FE setup/generation/IO/audit wall is separate. No speedup applies to rejected requests; no Dalton,1ms or clinical speedup is inferred.']
  if 'all_frozen_model_timings' in r:
   rows+=['','| Frozen ensemble | Resident mean/variance(ms) | With input processing(ms) | With endpoint/stress-state checks(ms) |','|---|---:|---:|---:|']
   for key,t in r['all_frozen_model_timings'].items():rows.append(f'| {key} | {t["resident"]["median_s"]*1000:.2f} | {t["input_processing"]["median_s"]*1000:.2f} | {t["endpoint_and_stress_state_J_checks"]["median_s"]*1000:.2f} |')
 rows+=['', '**Reproduction.** After original solver/data setup, use `make dynamic-study` in this cached workspace. A clean checkout contains recorded metrics but omits checkpoints: use `make dynamic-reproduce` to retrain missing weights and explicitly label the same-case replay as repeated benchmark reproduction. Use `make dynamic-benchmark` for recorded isolated timings; reproduction forces fresh timing queries. Configs define every geometry, waveform, seed and split; large arrays/checkpoints/logs remain ignored. The existing report is the only results Markdown. No paper directory or manuscript is created.', '']
 return rows
